<?php
declare(strict_types=1);

require dirname(__DIR__) . '/app/bootstrap.php';
$admin=require_role('admin');$id=(int)($_GET['id']??0);
$statement=db()->prepare('SELECT u.*,pp.headline,pp.bio,pp.years_experience,pp.availability_text,pp.verification_status,pp.verification_notes FROM users u LEFT JOIN provider_profiles pp ON pp.user_id=u.id WHERE u.id=?');$statement->execute([$id]);$target=$statement->fetch();
if(!$target){http_response_code(404);require dirname(__DIR__).'/templates/error-404.php';exit;}
$providerCategories=[];$providerDistricts=[];
if($target['role']==='provider'){$s=db()->prepare('SELECT c.name FROM provider_categories pc JOIN categories c ON c.id=pc.category_id WHERE pc.provider_id=? ORDER BY c.sort_order');$s->execute([$id]);$providerCategories=$s->fetchAll(PDO::FETCH_COLUMN);$s=db()->prepare('SELECT d.name FROM provider_districts pd JOIN districts d ON d.id=pd.district_id WHERE pd.provider_id=? ORDER BY d.name');$s->execute([$id]);$providerDistricts=$s->fetchAll(PDO::FETCH_COLUMN);}
$pageTitle='Usuario #'.$id;$pageSubtitle=$target['full_name'];$activeDashboard='users';require dirname(__DIR__).'/templates/dashboard-header.php';
?>
<div class="page-head"><div><h2><?=e($target['full_name'])?></h2><p><?=e(['client'=>'Cliente','provider'=>'Proveedor','admin'=>'Administrador'][$target['role']])?> · registro <?=e(date_pe($target['created_at']))?></p></div><div class="page-actions"><a class="btn btn-secondary" href="<?=e(url('admin/users.php'))?>">Volver</a></div></div>
<div class="panel-grid"><section class="panel"><div class="panel-header"><h2>Datos de cuenta</h2></div><div class="panel-body"><div class="detail-list"><div class="detail-row"><span>Celular</span><strong><?=e($target['phone'])?></strong></div><div class="detail-row"><span>Correo</span><strong><?=e($target['email']??'Sin correo')?></strong></div><div class="detail-row"><span>Estado</span><strong><?=e(status_label($target['status']))?></strong></div><div class="detail-row"><span>Último acceso</span><strong><?=e(date_pe($target['last_login_at'],true))?></strong></div></div></div></section>
<aside class="panel"><div class="panel-header"><h2>Acciones administrativas</h2></div><div class="panel-body form-stack"><?php if($target['role']!=='admin'):?><form action="<?=e(url('actions.php'))?>" method="post" data-confirm="¿Cambiar el estado de esta cuenta?"><?=csrf_field()?><input type="hidden" name="action" value="admin_user_status"><input type="hidden" name="user_id" value="<?=$id?>"><input type="hidden" name="status" value="<?=$target['status']==='active'?'suspended':'active'?>"><button class="btn <?=$target['status']==='active'?'btn-danger':'btn-primary'?> btn-block" type="submit"><?=$target['status']==='active'?'Suspender cuenta':'Reactivar cuenta'?></button></form><form action="<?=e(url('actions.php'))?>" method="post" data-confirm="Se generará una contraseña temporal. ¿Continuar?"><?=csrf_field()?><input type="hidden" name="action" value="admin_reset_password"><input type="hidden" name="user_id" value="<?=$id?>"><button class="btn btn-secondary btn-block" type="submit">Generar contraseña temporal</button></form><?php else:?><div class="alert alert-info">Las cuentas administradoras gestionan su seguridad desde Mi cuenta.</div><?php endif;?></div></aside></div>
<?php if($target['role']==='provider'):?><section class="panel"><div class="panel-header"><div><h2>Perfil profesional</h2><p>Revisa la información declarada antes de aprobar.</p></div><span class="status status-<?=e(status_class($target['verification_status']))?>"><?=e(status_label($target['verification_status']))?></span></div><div class="panel-body"><div class="alert alert-info">La aprobación confirma una revisión administrativa del perfil; no certifica identidad, antecedentes ni capacidad técnica.</div><h3><?=e($target['headline']?:'Sin titular')?></h3><div class="description-box"><?=e($target['bio']?:'El proveedor no completó su descripción.')?></div><div class="detail-list"><div class="detail-row"><span>Experiencia declarada</span><strong><?=(int)$target['years_experience']?> años</strong></div><div class="detail-row"><span>Disponibilidad</span><strong><?=e($target['availability_text']?:'Sin completar')?></strong></div></div><div class="chip-row"><?php foreach($providerCategories as $name):?><span class="chip"><?=e($name)?></span><?php endforeach;?></div><div class="chip-row"><?php foreach($providerDistricts as $name):?><span class="chip"><?=e($name)?></span><?php endforeach;?></div><form class="form-stack" action="<?=e(url('actions.php'))?>" method="post"><?=csrf_field()?><input type="hidden" name="action" value="admin_provider_verify"><input type="hidden" name="provider_id" value="<?=$id?>"><div class="field"><label for="verification_status">Decisión</label><select id="verification_status" name="verification_status"><option value="pending"<?=selected($target['verification_status'],'pending')?>>Pendiente</option><option value="verified"<?=selected($target['verification_status'],'verified')?>>Aprobar perfil</option><option value="rejected"<?=selected($target['verification_status'],'rejected')?>>Rechazar y solicitar cambios</option></select></div><div class="field"><label for="verification_notes">Notas para el proveedor</label><textarea id="verification_notes" name="verification_notes" maxlength="500"><?=e($target['verification_notes']??'')?></textarea></div><button class="btn btn-primary" type="submit">Guardar revisión</button></form></div></section><?php endif;?>
